#include "stdafx.h"#include "AND.h"KAND::KAND(): m_CurParameterID(-1), m_ReadParams( 0 ){}static LPCSTR s_MyParameters[]={  "Invert Input",};BOOL KAND::OnParsingSingleText( std::string &szText, RECTL *rc ){  if( m_CurParameterID!=-1 )  {    AddParam( szLast.c_str(), szText.c_str() );    szLast.clear();    CStringA val( szText.c_str() );    if( !val.Compare("NO") )      m_InversedPins.back().append( " = FALSE" );    else if( !val.Compare("YES") )      m_InversedPins.back().append( " = TRUE" );    else    {      ASSD( 0 );    }    m_CurParameterID = -1;    m_ReadParams++;    return TRUE;//сделать преобразование параметра к виду, пригодному для формирования исполняемого кода  }  for( int i=0; i<_countof(s_MyParameters); i++ )  {    if( szText.find(s_MyParameters[i])==0 )    {      szLast = szText;      m_CurParameterID = i;      CStringA inv;      inv.Format( "InvertInput%d", m_ReadParams );      m_InversedPins.push_back( inv.GetBuffer() );      return TRUE;    }  }  return FALSE;}